    "name": "男性变身魔法少女",
    "scenarios": [
      {
        "type": "变身成为女性",
        "description": "完全变成女性形态"
      },
      {
        "type": "保持男性",
        "description": "变得非常美丽，比绝大部分女性都美丽，但保留男性的性征"
      }
