    "平民阶级有些人会尝试匿藏魔法少女,对其进行洗脑或改造,以实现自己的目的.哪怕冒着被贵族发现的风险,魔法少女的力量也值得他们这样做",
    "奴仆阶级的魔法少女最为团结,她们由于遭受了非人的压迫,所以成为魔法少女的概率很高.成为魔法少女后,基本上都会尝试解放奴仆阶级"
  ],
  "location_info": {
    "world_info": "",
    "main_location": [
      {
        "name": "永恒之都",
        "description": "永恒之都是贵族阶级的中心，也是整个社会的权力枢纽。这里的建筑用最先进的技术和奢华材料打造，悬浮在高天之上，代表着贵族无可匹敌的财富和地位。天际线上充斥着浮岛与透明玻璃桥，彰显出对科技的极致控制。可以通过多处超级电梯快速往返地面。",
        "functionality": [
          {
            "name": "寰宇塔",
            "description": "掌控教育与知识研究的重要据点，是寰宇智者派系的大本营，封锁了顶尖的数据存储设备和科学实验室，普通人无法接近这些区域。"
          },
          {
            "name": "织网宫",
            "description": "负责全球经济流向与资源管理，这里是织网者获取并发布交易、分配资源策略、巩固家族资产的重要基地。"
          },
          {
            "name": "天启军部总部",
            "description": "军事力量“天启”的指挥中心，用于操控全球全息兵器系统，同时监控并镇压潜在的不满势力，从平民叛乱到奴仆骚动。"
          },
          {
            "name": "小型浮岛",
            "description": "贵族阶级们居住的地方，一个或数个贵族控制一个浮岛，根据自己的喜好自定义。"
          },
          {
            "name": "超级电梯",
            "description": "往返地面的通道，贵族可以带人上下，必须由贵族带领才可启动。拥有强大的机器人隐形部队全天监控"
          }
        ]
      },
      {
        "name": "仆从院",
        "description": "仆从院是仆人阶级生活和教育的区域，被隔离开来。由大量的教育机器人和一些平民工作人员与极少数的贵族管理者控制。",
        "functionality": [
          {
            "name": "仆从学校",
            "description": "巨大的高科技学校，冷漠且无情。奴仆们在其中接受教育，为成为好的奴仆而努力。内设由家务教育，性教育等等。也会进行基因改造，意识纠正来完善奴仆。"
          },
          {
            "name": "废弃品处理所",
            "description": "未能通过评估或失去使用价值后的奴仆将会送往此地处理重分配，有极大概率沦为‘废弃品’用于繁殖以维持劳工作业链延续性."
          },
          {
            "name": "仆从宿舍",
            "description": "仆从居住的地方.有大量监控。"
          }
        ]
      },
      {
        "name": "中央集市",
        "description": "横跨各个阶层，由多个高塔组成商业区。虽然名义上开放给所有平民，但仅有获得许可凭证的人能够进入更高级奢侈区域。",
        "functionality": [
          {
            "name": "地下竞价拍卖会",
            "description": "暗中进行一年一度法令禁止但广受瞩目的非法魔法少私人改造奴隶贸易，影响巨大却不被记录于官方文献."
          }
        ]
      }
    ]
  }
}

